contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test entry
    // We take a newBetLimit parameter and attempt to call AdjustBetAmounts.
    // The rule: when this contract is the owner (so the call does NOT revert),
    // afterwards currentBetLimit() equals newBetLimit, currentDifficulty() is unchanged,
    // and address(c).balance is unchanged.
    function run(uint256 newBetLimit) public payable {
        // read pre-state
        uint256 beforeBetLimit = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        uint256 beforeDifficulty = c.currentDifficulty(); if (__ESBMC_reverted()) return;
        uint256 beforeBalance = address(c).balance;

        bool reverted;
        // call that may revert depending on ownership
        c.AdjustBetAmounts(newBetLimit); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read post-state
        uint256 afterBetLimit = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        uint256 afterDifficulty = c.currentDifficulty(); if (__ESBMC_reverted()) return;
        uint256 afterBalance = address(c).balance;

        // If the call did not revert, this contract must have been the owner and
        // AdjustBetAmounts must have set the bet limit to newBetLimit while leaving
        // difficulty and balance unchanged. If the call reverted, we do not assert anything
        // about state (only that it reverted).
        assert(reverted || (!reverted && afterBetLimit == newBetLimit && afterDifficulty == beforeDifficulty && afterBalance == beforeBalance));
    }

    receive() external payable {}
}

