contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 newBetLimit) internal {
        uint256 beforeBetLimit;
        try c.currentBetLimit() returns (uint256 __r) { beforeBetLimit = __r; } catch { return; }
        uint256 beforeDifficulty;
        try c.currentDifficulty() returns (uint256 __r) { beforeDifficulty = __r; } catch { return; }
        uint256 beforeBalance = address(c).balance;
        bool reverted;
        try c.AdjustBetAmounts(newBetLimit) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterBetLimit;
        try c.currentBetLimit() returns (uint256 __r) { afterBetLimit = __r; } catch { return; }
        uint256 afterDifficulty;
        try c.currentDifficulty() returns (uint256 __r) { afterDifficulty = __r; } catch { return; }
        uint256 afterBalance = address(c).balance;
        assertTrue(reverted || (!reverted && afterBetLimit == newBetLimit && afterDifficulty == beforeDifficulty && afterBalance == beforeBalance));
    }

    function testFuzz_run(uint256 newBetLimit) public {
        _run(newBetLimit);
    }

    receive() external payable {}
}
